# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. İSMAİL (AS): MEKKE\'YE YERLEŞME, ZEMZEM VE SA\'Y İBADETİ</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Mekke Vadisine Yerleşim</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Babası: Hz. İbrahim (as)</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Annesi: Hz. Hacer</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Allah\'ın emriyle ıssız ve kurak</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  Mekke vadisine yerleştirildiler.</text>\n  <text x="40" y="180" font-size="11" fill="#334155">• Hz. İbrahim ailesi için bereket</text>\n  <text x="40" y="196" font-size="11" fill="#334155">  ve tevhit duası yaptı (İbrahim, 37).</text>\n  <text x="130" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Tevekkül ve Teslimiyet</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Sa\'y ve Zemzem Mucizesi</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Sular tükenince Hz. Hacer su</text>\n  <text x="260" y="114" font-size="11" fill="#334155">  aramak için Safa ve Merve</text>\n  <text x="260" y="130" font-size="11" fill="#334155">  tepeleri arasında 7 kez koştu.</text>\n  <text x="260" y="152" font-size="11" fill="#334155">• Bu arayış hac ve umredeki</text>\n  <text x="260" y="168" font-size="11" fill="#334155">  \'Sa\'y\' ibadetinin kaynağı oldu.</text>\n  <text x="260" y="190" font-size="11" fill="#334155">• Hz. İsmail\'in topuklarının</text>\n  <text x="260" y="206" font-size="11" fill="#334155">  altından Zemzem suyu fışkırdı.</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Cürhüm Kabilesi Mekke\'ye Yerleşti</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Kâbe\'nin İnşası (Beytullah)</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Hz. İbrahim ve Hz. İsmail</text>\n  <text x="480" y="114" font-size="11" fill="#334155">  birlikte Kâbe\'nin temellerini</text>\n  <text x="480" y="130" font-size="11" fill="#334155">  yükselttiler (Bakara, 127).</text>\n  <text x="480" y="152" font-size="11" fill="#334155">• Hz. İsmail taş taşıdı, babası</text>\n  <text x="480" y="168" font-size="11" fill="#334155">  duvarları ördü (Makam-ı İbrahim).</text>\n  <text x="480" y="190" font-size="11" fill="#334155">• Hacerü\'l-Esved köşeye kondu</text>\n  <text x="480" y="206" font-size="11" fill="#334155">  ve insanlara hac ilan edildi.</text>\n  <text x="570" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Tevhit Merkezi: Kâbe</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KURBAN İBADETİ İLE HZ. İBRAHİM VE HZ. İSMAİL KISSASI İLİŞKİSİ</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Sâffât Suresi 102-107: İmtihan ve Teslimiyet</text>\n  <text x="44" y="98" font-size="11" fill="#334155">1. Rüya ile İmtihan: Hz. İbrahim rüyasında oğlunu</text>\n  <text x="44" y="114" font-size="11" fill="#334155">   kurban ettiğini gördü ve durumu Hz. İsmail\'e açtı.</text>\n  <text x="44" y="136" font-size="11" fill="#334155">2. Hz. İsmail\'in Cevabı: "Babacığım! Sana emredileni</text>\n  <text x="44" y="152" font-size="11" fill="#334155">   yap; inşallah beni sabredenlerden bulacaksın."</text>\n  <text x="44" y="174" font-size="11" fill="#334155">3. Şeytanın Taşlanması: Mina\'da şeytanın vesvesesini</text>\n  <text x="44" y="190" font-size="11" fill="#334155">   taşlayarak reddettiler (Cemerat / Şeytan taşlama).</text>\n  <text x="183" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">4. İlahi Lütufla Koç Gönderilmesi ve Kurban İbadeti</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hz. İsmail\'in Kur\'an\'da Övülen Üstün Ahlakı</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• Sadıkü\'l-Va\'d (Sözünde duran / Meryem, 54)</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">• Sabır, tevekkül ve Allah\'a tam teslimiyet</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• Anne ve babaya derin saygı ve itaat</text>\n  <text x="378" y="172" font-size="11.5" fill="#334155">• Ailesine namazı ve zekâtı emretmesi (Meryem, 55)</text>\n  <text x="378" y="196" font-size="11.5" fill="#334155">• Peygamberimiz Hz. Muhammed\'in (sav) soy atası</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">"O, sözünde sadıktı; resul ve nebi idi."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HAC VE KURBAN İBADETİNİN KÜLTÜRÜMÜZE YANSIMALARI (DKAB.7.2.3)</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. Tarihî ve Kültürel Gelenekler</text>\n  <text x="40" y="100" font-size="11" fill="#334155">• Surre Alayları: Osmanlı\'da</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  Mekke ve Medine\'ye (Haremeyn)</text>\n  <text x="40" y="132" font-size="11" fill="#334155">  hediyeler gönderilen merasim.</text>\n  <text x="40" y="156" font-size="11" fill="#334155">• Hacı Uğurlama ve Karşılama:</text>\n  <text x="40" y="172" font-size="11" fill="#334155">  Dualar, ilahiler, zemzem ve</text>\n  <text x="40" y="188" font-size="11" fill="#334155">  hurma ikramı geleneği.</text>\n  <text x="130" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Haremeyn Sevgisi</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Bayramlaşma ve Paylaşma</text>\n  <text x="260" y="100" font-size="11" fill="#334155">• Teşrik Tekbirleri: Arefe sabahından</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  bayramın 4. günü ikindiye kadar.</text>\n  <text x="260" y="140" font-size="11" fill="#334155">• Kurban Paylaşımı: Üçe bölünerek</text>\n  <text x="260" y="156" font-size="11" fill="#334155">  yoksullara, komşulara ve aileye.</text>\n  <text x="260" y="180" font-size="11" fill="#334155">• Büyükleri ve kabirleri ziyaret,</text>\n  <text x="260" y="196" font-size="11" fill="#334155">  dargınların barıştırılması.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Yardımlaşma ve Kardeşlik</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">3. Dil, Edebiyat ve Değerler</text>\n  <text x="480" y="100" font-size="11" fill="#334155">• Deyimler: "İsmail gibi teslim</text>\n  <text x="480" y="116" font-size="11" fill="#334155">  olmak", "Kurban olduğum",</text>\n  <text x="480" y="132" font-size="11" fill="#334155">  "Koçyiğit", "Kâbe\'yi görmek".</text>\n  <text x="480" y="156" font-size="11" fill="#334155">• Kurbanlık koça kına yakılması</text>\n  <text x="480" y="172" font-size="11" fill="#334155">  (Hz. İsmail kıssasına atıf).</text>\n  <text x="480" y="196" font-size="11" fill="#334155">• Vakıf ve Kızılay vekâlet bağışı.</text>\n  <text x="570" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Milli ve Manevi Miras</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
